  @Mock private Node mockChild;
  @Mock private Node mockNextChild;
  @Mock private Compiler mockCompiler;

  private TypedScopeCreator.AbstractScopeBuilder scopeBuilder;

  @Before
  public void setUp() {
    // Since AbstractScopeBuilder is an abstract class, we use a minimal implementation or spy
    // In JSComp, TypedScopeCreator.AbstractScopeBuilder is usually part of a phase.
    // We will mock the necessary dependencies for the internal logic.

    scopeBuilder = spy(new TypedScopeCreator.AbstractScopeBuilder(
        mockCompiler, 
        new ErrorReporter(), 
        mockScope) {
      @Override
      public void visit(NodeTraversal t, Node n, Node parent) {
        // No-op implementation for testing shouldTraverse
      }
    });

    // Setup default scope behavior
    when(mockScope.getRootNode()).thenReturn(mockRootNode);
    when(mockTraversal.getInputId()).thenReturn("test-input-id");
  }

  @Test
  public void testShouldTraverse_ParentIsNull_ReturnsTrue() {
    when(mockNode.isFunction()).thenReturn(false);
    when(mockNode.isScript()).thenReturn(false);

    boolean result = scopeBuilder.shouldTraverse(mockTraversal, mockNode, null);

    assertThat(result).isTrue();
  }

  @Test
  public void testShouldTraverse_ParentIsFunction_ButNIsFirstChild_ReturnsTrue() {
    when(mockNode.isFunction()).thenReturn(false);
    when(mockNode.isScript()).thenReturn(false);
    when(mockParent.isFunction()).thenReturn(true);
    when(mockParent.getFirstChild()).thenReturn(mockNode);

    boolean result = scopeBuilder.shouldTraverse(mockTraversal, mockNode, mockParent);

    assertThat(result).isTrue();
  }

  @Test
  public void testShouldTraverse_ParentIsRootNode_ReturnsTrue() {
    when(mockNode.isFunction()).thenReturn(false);
    when(mockNode.isScript()).thenReturn(false);
    when(mockParent.isFunction()).thenReturn(true);
    when(mockParent.getFirstChild()).thenReturn(mockNode);
    when(mockScope.getRootNode()).thenReturn(mockParent);

    boolean result = scopeBuilder.shouldTraverse(mockTraversal, mockNode, mockParent);

    assertThat(result).isTrue();
  }

  @Test
  public void testShouldTraverse_ParentIsFunction_AndNIsNotFirstChild_ReturnsFalse() {
    when(mockNode.isFunction()).thenReturn(false);
    when(mockNode.isScript()).thenReturn(false);
    when(mockParent.isFunction()).thenReturn(true);
    when(mockParent.getFirstChild()).thenReturn(mockChild); // mockNode is not first child

    boolean result = scopeBuilder.shouldTraverse(mockTraversal, mockNode, mockParent);

    assertThat(result).isFalse();
  }

